package cn.pawday.care;
import cn.pawday.audit.AuditWriter;
import cn.pawday.common.Api.Failure;
import cn.pawday.common.IdempotentCommandExecutor;
import cn.pawday.identity.*;
import cn.pawday.publishing.PublishingSupport;
import static cn.pawday.publishing.PublishingSupport.*;
import cn.pawday.search.ProductSearchFilter;
import java.nio.charset.StandardCharsets;
import java.util.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.stereotype.Service;
@Service public class PurchaseRequestService {
 private final PublishingSupport p;private final IdempotentCommandExecutor commands;private final AuditWriter audit;private final Crypto crypto;private final AuthService auth;
 public PurchaseRequestService(PublishingSupport p,IdempotentCommandExecutor commands,AuditWriter audit,Crypto crypto,AuthService auth){this.p=p;this.commands=commands;this.audit=audit;this.crypto=crypto;this.auth=auth;}
 private void consumer(Actor a){if(a.realm()!=Actor.Realm.CONSUMER||a.userId()==null)throw new Failure(403,"PERMISSION_DENIED");}
 private void read(Actor a){if(a.realm()==Actor.Realm.CONSUMER)consumer(a);else permission(a,Actor.Realm.ADMIN,"purchase-request.read");}
 private Map<String,Object> owned(Actor a,UUID id,boolean lock){read(a);return a.realm()==Actor.Realm.CONSUMER?p.one("SELECT * FROM purchase_requests WHERE id=? AND user_id=?"+(lock?" FOR UPDATE":""),id,a.userId()):p.one("SELECT * FROM purchase_requests WHERE id=?"+(lock?" FOR UPDATE":""),id);}
 private Map<String,Object> view(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();for(String k:List.of("id","status","version","created_at","updated_at"))out.put(k,p.view(row).get(k));out.putAll(p.json.readValue(new String(crypto.decrypt(row.get("request_cipher").toString()),StandardCharsets.UTF_8),Map.class));out.put("response",row.get("response_cipher")==null?null:new String(crypto.decrypt(row.get("response_cipher").toString()),StandardCharsets.UTF_8));return out;}
 private Map<String,Object> ack(Map<String,Object>row){return Map.of("id",row.get("id"),"status",row.get("status"),"version",row.get("version"));}
 private void history(Actor a,UUID id){p.db.update("INSERT INTO purchase_request_changes(id,request_id,actor_id,status,version,request_cipher,response_cipher) SELECT ?,id,?,status,version,request_cipher,response_cipher FROM purchase_requests WHERE id=?",UUID.randomUUID(),a.principalId(),id);}
 public List<Map<String,Object>> list(Actor a,UUID cursor,int limit,String status){read(a);limit(limit);if(status!=null&&!Set.of("OPEN","REVIEWING","RESOLVED","REJECTED","CANCELLED").contains(status))throw new Failure(400,"VALIDATION_ERROR");var args=new ArrayList<Object>();String sql="SELECT * FROM purchase_requests WHERE id>?";args.add(cursor);if(a.realm()==Actor.Realm.CONSUMER){sql+=" AND user_id=?";args.add(a.userId());}if(status!=null){sql+=" AND status=?";args.add(status);}args.add(limit+1);return p.db.queryForList(sql+" ORDER BY id LIMIT ?",args.toArray()).stream().map(this::view).toList();}
 public Map<String,Object> detail(Actor a,UUID id,HttpServletRequest r){var row=owned(a,id,false);if(a.realm()==Actor.Realm.ADMIN)audit.write(a,"purchase-request.read","PURCHASE_REQUEST",id.toString(),Map.of(),Map.of("access","DETAIL"),r);return view(row);}
 public List<Map<String,Object>> history(Actor a,UUID id,UUID cursor,int limit){owned(a,id,false);limit(limit);return p.db.queryForList("SELECT id,request_id,status,version,created_at FROM purchase_request_changes WHERE request_id=? AND id>? ORDER BY id LIMIT ?",id,cursor,limit+1).stream().map(p::view).toList();}
 public Map<String,Object> create(Actor a,Map<String,Object>b,String key,HttpServletRequest r){consumer(a);fields(b,"title","description","search_context");String title=text(b.get("title"),160).trim(),description=b.get("description") instanceof String s&&s.length()<=1000?s.trim():null;if(description==null)throw new Failure(400,"VALIDATION_ERROR");if(!(b.get("search_context") instanceof Map<?,?>context))throw new Failure(400,"VALIDATION_ERROR");Map<String,String> filters=new TreeMap<>();context.forEach((k,v)->{if(!(k instanceof String sk)||!(v instanceof String sv))throw new Failure(400,"VALIDATION_ERROR");filters.put(sk,sv);});var canonical=new TreeMap<String,Object>(Map.of("title",title,"description",description,"search_context",ProductSearchFilter.parse(filters).canonical()));String hash=crypto.hash(p.json.writeValueAsString(canonical));return commands.command(a,"purchase-request.create",key,canonical,()->{
  p.db.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","purchase-request:"+a.userId());var old=p.db.queryForList("SELECT * FROM purchase_requests WHERE user_id=? AND content_hash=? AND status IN ('OPEN','REVIEWING')",a.userId(),hash);if(!old.isEmpty())return ack(old.getFirst());
  if(p.db.queryForObject("SELECT count(*) FROM purchase_requests WHERE user_id=? AND created_at>clock_timestamp()-interval '1 day'",Integer.class,a.userId())>=20)throw new Failure(429,"PURCHASE_REQUEST_LIMIT");UUID id=UUID.randomUUID();p.db.update("INSERT INTO purchase_requests(id,user_id,request_cipher,content_hash) VALUES (?,?,?,?)",id,a.userId(),crypto.encrypt(p.json.writeValueAsBytes(canonical)),hash);history(a,id);audit.write(a,"purchase-request.create","PURCHASE_REQUEST",id.toString(),Map.of(),Map.of("status","OPEN"),r);return ack(owned(a,id,false));
 });}
 public Map<String,Object> cancel(Actor a,UUID id,String match,String key,HttpServletRequest r){consumer(a);long expected=version(match);return commands.command(a,"purchase-request.cancel:"+id,key,Map.of("version",expected),()->{var row=owned(a,id,true);sameVersion(row,expected);if(!Set.of("OPEN","REVIEWING").contains(row.get("status")))throw new Failure(409,"PURCHASE_REQUEST_CLOSED");p.db.update("UPDATE purchase_requests SET status='CANCELLED',version=version+1,updated_at=clock_timestamp() WHERE id=?",id);history(a,id);audit.write(a,"purchase-request.cancel","PURCHASE_REQUEST",id.toString(),Map.of(),Map.of("status","CANCELLED","version",expected+1),r);return ack(owned(a,id,false));});}
 public Map<String,Object> handle(Actor a,UUID id,Map<String,Object>b,String match,String key,String proof,HttpServletRequest r){permission(a,Actor.Realm.ADMIN,"purchase-request.manage");fields(b,"status","response");String status=text(b.get("status"),16),response=text(b.get("response"),500).trim();if(!Set.of("REVIEWING","RESOLVED","REJECTED").contains(status))throw new Failure(400,"VALIDATION_ERROR");long expected=version(match);return commands.command(a,"purchase-request.manage:"+id,key,Map.of("body",b,"version",expected),()->{var row=owned(a,id,true);sameVersion(row,expected);if(!Set.of("OPEN","REVIEWING").contains(row.get("status"))||status.equals(row.get("status")))throw new Failure(409,"PURCHASE_REQUEST_CLOSED");auth.consumeProof(a,"purchase-request.manage",proof);p.db.update("UPDATE purchase_requests SET status=?,response_cipher=?,version=version+1,updated_at=clock_timestamp() WHERE id=?",status,crypto.encrypt(response.getBytes(StandardCharsets.UTF_8)),id);history(a,id);audit.write(a,"purchase-request.manage","PURCHASE_REQUEST",id.toString(),Map.of(),Map.of("status",status,"version",expected+1),r);return ack(owned(a,id,false));});}
}
